// AddFile uploads content as a multipart/form-data file to /files. Unlike
// Add, which takes a pre-encoded body, AddFile builds the multipart body for
// you from a file name and reader, so you do not have to construct it
// yourself. Association fields (deal, person, org, etc.) can be attached via
// the WithFiles* options.
//
// The body is buffered into a replayable *bytes.Reader, so retries (e.g. on
// 429 during rate-limited bulk imports) work out of the box.
func (s *FilesService) AddFile(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
	if fileName == "" || content == nil {
		return nil, fmt.Errorf("file name and content are required")
	}
	cfg := newFilesOptions(opts)

	contentType, body, err := multipartbody.NewFileWithFields("file", fileName, content, cfg.multipartFields)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

