func TestFilesService_AddFile(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}

		mr, err := r.MultipartReader()
		if err != nil {
			t.Fatalf("multipart reader: %v", err)
		}
		var partNames []string
		var fileContent string
		for {
			part, err := mr.NextPart()
			if err == io.EOF {
				break
			}
			if err != nil {
				t.Fatalf("next part: %v", err)
			}
			partNames = append(partNames, part.FormName())
			if part.FormName() == "file" {
				if got := part.FileName(); got != "doc.pdf" {
					t.Fatalf("unexpected file name: %q", got)
				}
				b, _ := io.ReadAll(part)
				fileContent = string(b)
			}
		}
		if len(partNames) != 1 || partNames[0] != "file" {
			t.Fatalf("unexpected parts: %#v", partNames)
		}
		if fileContent != "payload" {
			t.Fatalf("unexpected file content: %q", fileContent)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"doc.pdf"}}`))
	})

	file, err := client.Files.AddFile(context.Background(), "doc.pdf", strings.NewReader("payload"))
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
	if file.ID != 12 || file.Name != "doc.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_AddFile_AssociationFields(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}

		mr, err := r.MultipartReader()
		if err != nil {
			t.Fatalf("multipart reader: %v", err)
		}
		fields := map[string]string{}
		var fileFound bool
		for {
			part, err := mr.NextPart()
			if err == io.EOF {
				break
			}
			if err != nil {
				t.Fatalf("next part: %v", err)
			}
			if part.FormName() == "file" {
				fileFound = true
				continue
			}
			b, _ := io.ReadAll(part)
			fields[part.FormName()] = string(b)
		}
		if !fileFound {
			t.Fatalf("expected a file part")
		}
		if fields["deal_id"] != "7" || fields["person_id"] != "9" || fields["lead_id"] != "abc" {
			t.Fatalf("unexpected fields: %#v", fields)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"doc.pdf"}}`))
	})

	_, err := client.Files.AddFile(
		context.Background(),
		"doc.pdf",
		strings.NewReader("payload"),
		WithFilesDealID(7),
		WithFilesPersonID(9),
		WithFilesLeadID("abc"),
	)
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
}

func TestFilesService_AddFile_RequiresFileNameAndContent(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		t.Fatalf("unexpected call")
	})

	if _, err := client.Files.AddFile(context.Background(), "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, err := client.Files.AddFile(context.Background(), "x.pdf", nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

