package multipartbody

import (
	"io"
	"mime/multipart"
	"strings"
	"testing"
)

func TestNewFileWithFields(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFileWithFields("file", "a.txt", strings.NewReader("hello"), map[string]string{
		"deal_id": "7",
	})
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}
	if contentType == "" {
		t.Fatalf("expected a content type")
	}

	mr := multipart.NewReader(body, boundaryFromContentType(t, contentType))
	var fields = map[string]string{}
	var fileContent string
	var fileFound bool
	for {
		part, err := mr.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		if part.FormName() == "file" {
			fileFound = true
			if part.FileName() != "a.txt" {
				t.Fatalf("unexpected file name: %q", part.FileName())
			}
			b, _ := io.ReadAll(part)
			fileContent = string(b)
		} else {
			b, _ := io.ReadAll(part)
			fields[part.FormName()] = string(b)
		}
	}
	if !fileFound {
		t.Fatalf("expected a file part")
	}
	if fileContent != "hello" {
		t.Fatalf("unexpected file content: %q", fileContent)
	}
	if fields["deal_id"] != "7" {
		t.Fatalf("unexpected fields: %#v", fields)
	}
}

func TestNewFileWithFields_Replayable(t *testing.T) {
	t.Parallel()

	_, body, err := NewFileWithFields("file", "a.txt", strings.NewReader("x"), nil)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}
	first, _ := io.ReadAll(body)
	if _, err := body.Seek(0, io.SeekStart); err != nil {
		t.Fatalf("seek: %v", err)
	}
	second, _ := io.ReadAll(body)
	if string(first) != string(second) {
		t.Fatalf("body not replayable")
	}
}

func TestNewFileWithFields_Validates(t *testing.T) {
	t.Parallel()

	if _, _, err := NewFileWithFields("", "a.txt", strings.NewReader("x"), nil); err == nil {
		t.Fatalf("expected error for empty field name")
	}
	if _, _, err := NewFileWithFields("file", "", strings.NewReader("x"), nil); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, _, err := NewFileWithFields("file", "a.txt", nil, nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

func boundaryFromContentType(t *testing.T, contentType string) string {
	t.Helper()
	for _, part := range strings.Split(contentType, ";") {
		part = strings.TrimSpace(part)
		if strings.HasPrefix(part, "boundary=") {
			return strings.TrimPrefix(part, "boundary=")
		}
	}
	t.Fatalf("no boundary in content type %q", contentType)
	return ""
}

